def score(program: str) -> float:
    try:
        import ast
        tree = ast.parse(program)
        nodes = list(ast.walk(tree))
        if not nodes:
            return 0.0
        names = sum(1 for n in nodes if isinstance(n, ast.Name))
        ratio = names / len(nodes)
        return min(1.0, max(0.0, ratio))
    except:
        return 0.0

