def score(program: str) -> float:
    try:
        n = len(program)
        if n == 0:
            return 0.0
        alnum = sum(1 for c in program if c.isalnum()) / n
        v = 0.8 * n / (n + 600.0) + 0.2 * alnum
        return max(0.0, min(1.0, v))
    except Exception:
        return 0.0

